"use client";

import {
  RiFileCopyLine,
} from "@remixicon/react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { Button } from "../../base/buttons/button";
import { IconButton } from "../../base/buttons/icon-button";
import { cx } from "../../utils/cx";
import { ConversationFeedback } from "../conversation/conversation-feedback";
import { AgentProgress } from "../agent-progress/agent-progress";
import {
  workspaceUserMessageClasses,
  AgentChangesPanel,
  AgentWorkspace,
  type AgentWorkspaceAppearance,
} from "./agent-workspace";

export interface AIChatMessage {
  id: string;
  role: "user" | "assistant";
  content: string;
}
export interface AIChatTemplateProps {
  /** Connect your own agent. Without this callback the screen plays a local demonstration. */
  workspace?: AgentWorkspaceAppearance;
  onSend?: (
    message: string,
    options: { signal: AbortSignal; messages: AIChatMessage[] },
  ) => Promise<string>;
  initialMessages?: AIChatMessage[];
  autoRun?: boolean;
  /** Opt into an embedded dashboard in Browser; the default panel is an empty placeholder. */
  enableBrowserPreview?: boolean;
  contained?: boolean;
  className?: string;
}
const PROMPT =
  "update our color tokens for dark mode and add a reusable theme toggle to the registry. run lint and a production build when you're done.";
const SUMMARY =
  "Done — the semantic dark-mode tokens and reusable theme toggle are wired. The toggle updates the root theme from one place and persists the selection:";

export { ConversationFeedback } from "../conversation/conversation-feedback";

function ExampleChangeSnippet() {
  const sample = `const root = document.documentElement;

const selectedTheme = root.classList.contains("dark")
  ? "light"
  : "dark";

root.classList.toggle("dark", selectedTheme === "dark");

localStorage.setItem("app:theme", selectedTheme);`;
  return (
    <div className="mb-2 overflow-hidden rounded-2xl border border-separator-border bg-background-full shadow-xs">
      <div className="flex items-center gap-2 border-b border-separator-border px-2.5 py-2">
        <span className="rounded-sm bg-status-purple-background px-1 text-[9px] leading-[14px] text-status-purple-text">
          TSX
        </span>
        <span className="flex-1 font-mono text-[11px] text-text-secondary">theme-toggle.tsx</span>
        <span className="font-mono text-[10px] text-emerald-700">+156</span>
        <span className="font-mono text-[10px] text-red-600">-23</span>
        <IconButton
          unstyled
          size="small"
          icon={RiFileCopyLine}
          aria-label="Copy example"
          className="size-4 text-foreground-icon-secondary"
          onClick={() => navigator.clipboard?.writeText(sample)}
        />
      </div>
      <pre className="max-h-[145px] overflow-auto p-2.5 font-mono text-[11px] leading-[18px] text-text-secondary">
        {sample.split("\n").map((line, i) => (
          <div key={i} className="flex gap-3">
            <span className="w-3 shrink-0 text-right text-text-tertiary">{i + 1}</span>
            <code className="whitespace-pre-wrap break-all">{line || " "}</code>
          </div>
        ))}
      </pre>
    </div>
  );
}

/** Timed preview with cancellable live-adapter support. No commands execute in the demo. */
export function AIChatTemplate({
  onSend,
  workspace,
  initialMessages,
  autoRun = true,
  enableBrowserPreview = false,
  contained,
  className,
}: AIChatTemplateProps = {}) {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<AIChatMessage[]>(
    initialMessages ??
      (autoRun && !onSend ? [{ id: "prompt", role: "user", content: PROMPT }] : []),
  );
  const [phase, setPhase] = useState<
    "idle" | "working" | "finishing" | "done" | "stopped" | "error"
  >(autoRun && !initialMessages && !onSend ? "working" : "idle");
  const [run, setRun] = useState(0);
  const [error, setError] = useState("");
  const controller = useRef<AbortController | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const generation = useRef(0);
  const reduced = useReducedMotion();
  const busy = phase === "working";
  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    setMounted(false);
    if (!busy || onSend) return;
    const id = setTimeout(() => setMounted(true), 1000);
    return () => clearTimeout(id);
  }, [busy, onSend, run]);
  const clear = () => {
    generation.current += 1;
    controller.current?.abort();
    if (timer.current) clearTimeout(timer.current);
  };
  useEffect(
    () => () => {
      controller.current?.abort();
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );
  useEffect(() => {
    if (!busy || onSend) return;
    const timeout = setTimeout(() => setPhase("finishing"), 18100);
    timer.current = timeout;
    return () => clearTimeout(timeout);
  }, [busy, onSend, run]);
  useEffect(() => {
    if (phase !== "finishing") return;
    const timeout = setTimeout(() => {
      setMessages((old) => [...old, { id: `answer-${run}`, role: "assistant", content: SUMMARY }]);
      setPhase("done");
    }, 300);
    timer.current = timeout;
    return () => clearTimeout(timeout);
  }, [phase, run]);
  const send = async (value: string, retryHistory?: AIChatMessage[]) => {
    const prompt = value.trim();
    if (!prompt) return;
    clear();
    const requestId = generation.current;
    const abort = new AbortController();
    controller.current = abort;
    const history = retryHistory ?? [
      ...messages,
      { id: `user-${requestId}`, role: "user" as const, content: prompt },
    ];
    setMessages(history);
    setInput("");
    setError("");
    setPhase("working");
    setRun(requestId);
    if (onSend) {
      try {
        const content = await onSend(prompt, { signal: abort.signal, messages: history });
        if (generation.current !== requestId || abort.signal.aborted) return;
        setMessages((old) => [...old, { id: `answer-${requestId}`, role: "assistant", content }]);
        setPhase("done");
      } catch (cause) {
        if (generation.current !== requestId || abort.signal.aborted) return;
        setError(cause instanceof Error ? cause.message : "The response could not be completed.");
        setPhase("error");
      }
    }
  };
  const retry = (responseId?: string) => {
    const responseIndex = responseId
      ? messages.findIndex((item) => item.id === responseId)
      : messages.length;
    const history = messages.slice(0, responseIndex);
    const userIndex = history.findLastIndex((item) => item.role === "user");
    if (userIndex >= 0) void send(history[userIndex].content, history.slice(0, userIndex + 1));
  };
  return (
    <AgentWorkspace
      navigationActions={!!onSend}
      {...workspace}
      kind="chat"
      input={input}
      onInputChange={setInput}
      onSubmit={(value) => void send(value)}
      onStop={() => {
        clear();
        setPhase("stopped");
      }}
      onNew={() => {
        clear();
        setMessages([]);
        setInput("");
        setError("");
        setPhase("idle");
      }}
      busy={onSend ? busy : false}
      thinking={busy && (onSend ? true : mounted)}
      contained={contained}
      className={className}
      panel={
        onSend ? (
          <p className="p-3 text-body-regular text-text-secondary">
            No file changes reported by this agent.
          </p>
        ) : (
          <>
            <p className="sr-only">Example file changes</p>
            <AgentChangesPanel
              enableBrowserPreview={enableBrowserPreview}
              filePath={workspace?.codeFilePath}
            />
          </>
        )
      }
    >
      {messages.length === 0 && (
        <div className="flex flex-1 flex-col justify-center py-20 text-center">
          <h1 className="text-title-2-medium text-text-primary">What would you like to build?</h1>
          <p className="pt-2 text-body-regular text-text-secondary">
            Start a conversation with your coding agent.
          </p>
        </div>
      )}
      {messages.map((message) => (
        <motion.div
          key={message.id}
          initial={run === 0 || reduced ? false : { opacity: 0, y: 8, filter: "blur(3px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          transition={{ duration: reduced ? 0 : 0.4, ease: [0.22, 1, 0.36, 1] }}
          className={cx(
            "text-body-regular text-text-primary",
            message.role === "user"
              ? workspaceUserMessageClasses
              : "w-full whitespace-pre-line",
          )}
        >
          <p>{message.content}</p>
          {message.role === "assistant" && (
            <div className="mt-2">
              {!onSend && <ExampleChangeSnippet />}
              <ConversationFeedback
                text={message.content}
                variant={onSend ? "default" : "subtle"}
                showRetry={!!onSend}
                onRetry={() => retry(message.id)}
                retryDisabled={busy}
              />
            </div>
          )}
        </motion.div>
      ))}
      <AnimatePresence>
        {busy && (
          <motion.div
            key={`run-${run}`}
            initial={run === 0 || reduced ? false : { opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="flex flex-col gap-3"
          >
            {onSend && (
              <p role="status" className="text-body-2-regular text-text-tertiary">
                Waiting for your agent…
              </p>
            )}
            {!onSend && mounted && (
              <AgentProgress
                stepDuration={3000}
                steps={[
                  "Read project files",
                  "Update and install light mode tokens",
                  "Implement dark mode tokens",
                  "Add reusable registered theme toggle",
                  "Run registry, lint and production build",
                ]}
              />
            )}
          </motion.div>
        )}
      </AnimatePresence>
      {phase === "stopped" && (
        <p role="status" className="text-body-regular text-text-secondary">
          Response stopped.
        </p>
      )}
      {phase === "error" && (
        <p role="alert" className="text-body-regular text-status-rose-text">
          {error}
        </p>
      )}
      {(phase === "stopped" || phase === "error") && (
        <Button size="small" variant="secondary" className="self-start" onClick={() => retry()}>
          Retry response
        </Button>
      )}
    </AgentWorkspace>
  );
}
